cd /workspaces/semio && node -e "
const kit = require('./compose/assets/compose/metabolism.kit.compose.json');
const diff = require('./compose/assets/compose/nakgin-capsule-tower.diff.design.compose.json');
const design = kit.designs.find(d => d.name === 'Nakagin Capsule Tower' && !d.parent);
console.log('Design pieces count:', design.pieces.length);
console.log('Design connections count:', design.connections.length);
console.log('Diff removed pieces:', diff.pieces.removed.length);
console.log('Diff updated pieces:', diff.pieces.updated.length);
console.log('Diff added pieces:', diff.pieces.added.length);
console.log('Diff removed connections:', diff.connections.removed.length);
console.log('Diff updated connections:', diff.connections.updated.length);
console.log('Diff added connections:', diff.connections.added.length);
// List the removed piece guids
const removedPieceGuids = new Set(diff.pieces.removed.map(r => r.guid));
const removedConnGuids = new Set(diff.connections.removed.map(r => r.guid));
const updatedPieceGuids = new Set(diff.pieces.updated.map(u => u.piece.guid));
const updatedConnGuids = new Set(diff.connections.updated.map(u => u.connection.guid));

// Build the with-diff design
const statusAttr = (status) => ({ guid: 'compose.diffStatus.' + status, key: 'compose.diffStatus', value: status });

const resultPieces = design.pieces.map(p => {
  const attrs = [...(p.attributes || [])];
  if (removedPieceGuids.has(p.guid)) {
    attrs.push(statusAttr('removed'));
    return { ...p, attributes: attrs };
  } else if (updatedPieceGuids.has(p.guid)) {
    attrs.push(statusAttr('modified'));
    return { ...p, attributes: attrs };
  } else {
    attrs.push(statusAttr('unchanged'));
    return { ...p, attributes: attrs };
  }
});
// add added pieces
for (const ap of diff.pieces.added) {
  const attrs = [...(ap.attributes || [])];
  attrs.push(statusAttr('added'));
  resultPieces.push({ ...ap, attributes: attrs });
}

const resultConns = design.connections.map(c => {
  const attrs = [...(c.attributes || [])];
  if (removedConnGuids.has(c.guid)) {
    attrs.push(statusAttr('removed'));
    return { ...c, attributes: attrs };
  } else if (updatedConnGuids.has(c.guid)) {
    attrs.push(statusAttr('modified'));
    return { ...c, attributes: attrs };
  } else {
    attrs.push(statusAttr('unchanged'));
    return { ...c, attributes: attrs };
  }
});
// add added connections
for (const ac of diff.connections.added) {
  const attrs = [...(ac.attributes || [])];
  attrs.push(statusAttr('added'));
  resultConns.push({ ...ac, attributes: attrs });
}

const result = { ...design };
result.pieces = resultPieces;
result.connections = resultConns;
// Write to file
const fs = require('fs');
fs.writeFileSync('./compose/assets/compose/nakagin-capsule-tower.with-diff.design.compose.json', JSON.stringify(result, null, 2));
console.log('Written with-diff asset');
console.log('Result pieces:', resultPieces.length);
console.log('Result connections:', resultConns.length);
"

