function statusAttr(status) {
  return { guid: "compose.diffStatus." + status, key: "compose.diffStatus", value: status };
}

var resultPieces = design.pieces.map(function(p) {
  var attrs = (p.attributes || []).slice();
  if (removedPieceGuids[p.guid]) { attrs.push(statusAttr("removed")); }
  else if (updatedPieceGuids[p.guid]) { attrs.push(statusAttr("modified")); }
  else { attrs.push(statusAttr("unchanged")); }
  var copy = Object.assign({}, p);
  copy.attributes = attrs;
  return copy;
});
(diff.pieces.added || []).forEach(function(ap) {
  var attrs = (ap.attributes || []).slice();
  attrs.push(statusAttr("added"));
  var copy = Object.assign({}, ap);
  copy.attributes = attrs;
  resultPieces.push(copy);
});

var resultConns = design.connections.map(function(c) {
  var attrs = (c.attributes || []).slice();
  if (removedConnGuids[c.guid]) { attrs.push(statusAttr("removed")); }
  else if (updatedConnGuids[c.guid]) { attrs.push(statusAttr("modified")); }
  else { attrs.push(statusAttr("unchanged")); }
  var copy = Object.assign({}, c);
  copy.attributes = attrs;
  return copy;
});
(diff.connections.added || []).forEach(function(ac) {
  var attrs = (ac.attributes || []).slice();
  attrs.push(statusAttr("added"));
  var copy = Object.assign({}, ac);
  copy.attributes = attrs;
  resultConns.push(copy);
});

var result = Object.assign({}, design);
result.pieces = resultPieces;
result.connections = resultConns;

var fs = require("fs");
fs.writeFileSync("./compose/assets/compose/nakagin-capsule-tower.with-diff.design.compose.json", JSON.stringify(result, null, 2));
console.log("Written. Pieces:", resultPieces.length, "Connections:", resultConns.length);
