public class WithDiff
{
    [Fact]
    public void Nakagin_Capsule_Tower_Design_With_Diff()
    {
        var kit = Tests.LoadAsset<Kit>("metabolism.kit.compose.json");
        var design = kit.Designs.First(d => d.Name == "Nakagin Capsule Tower" && d.Parent == null);
        var diff = Tests.LoadAsset<DesignDiff>("nakgin-capsule-tower.diff.design.compose.json");
        var expected = Tests.LoadAsset<Design>("nakagin-capsule-tower.with-diff.design.compose.json");

        var result = Design.WithDiff(design, diff);

        Assert.Equal(expected.Pieces.Count, result.Pieces.Count);
        Assert.Equal(expected.Connections.Count, result.Connections.Count);

        string GetStatus(List<Attribute> attrs)
            => attrs.FirstOrDefault(a => a.Key == "compose.diffStatus")?.Value ?? "";

        var pieceStatusCounts = result.Pieces
            .GroupBy(p => GetStatus(p.Attributes))
            .ToDictionary(g => g.Key, g => g.Count());
        Assert.Equal(163, pieceStatusCounts["unchanged"]);
        Assert.Equal(7, pieceStatusCounts["modified"]);
        Assert.Equal(10, pieceStatusCounts["removed"]);
        Assert.Equal(5, pieceStatusCounts["added"]);

        var connStatusCounts = result.Connections
            .GroupBy(c => GetStatus(c.Attributes))
            .ToDictionary(g => g.Key, g => g.Count());
        Assert.Equal(168, connStatusCounts["unchanged"]);
        Assert.Equal(1, connStatusCounts["modified"]);
        Assert.Equal(10, connStatusCounts["removed"]);
        Assert.Equal(4, connStatusCounts["added"]);
    }
}

